examples.template:
MonarchButton({{trigger}}, variant: .danger) { isOpen = true }
    .sheet(isPresented: $isOpen) {
        VStack(alignment: .leading, spacing: theme.spacing.space4) {
            if isFinished {
                MonarchBanner(
                    "\(count - failed.count) of \(count) \(noun) deleted",
                    message: failed.isEmpty ? "Every contact was deleted." : "Not deleted: \(failed.joined(separator: ", "))",
                    tone: failed.isEmpty ? .success : .warning
                )
                MonarchButton("Done", variant: .primary, fullWidth: true) { isOpen = false }
            } else if isRunning {
                ProgressView("\(done) of \(count) deleted", value: Double(done), total: Double(count))
                    .progressViewStyle(.monarchLinear)
            } else {
                Text({{trigger}}).monarchTextStyle(.heading).accessibilityAddTraits(.isHeader)
                Text("Check before you delete").monarchTextStyle(.subheading).accessibilityAddTraits(.isHeader)
                Text("This cannot be undone.")
                    .monarchTextStyle(.body)
                    .foregroundStyle(theme.colors.textMuted)
                VStack(alignment: .leading, spacing: theme.spacing.space1) {
                    Text("Selected").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
                    VStack(spacing: 0) {
                        ForEach(sample, id: \.self) { name in
                            Text(name)
                                .monarchTextStyle(.label)
                                .frame(maxWidth: .infinity, alignment: .leading)
                                .padding(theme.spacing.space3)
                            Divider()
                        }
                        Text("+\(count - sample.count) more")
                            .monarchTextStyle(.label)
                            .foregroundStyle(theme.colors.textMuted)
                            .frame(maxWidth: .infinity, alignment: .leading)
                            .padding(theme.spacing.space3)
                    }
                    .overlay(RoundedRectangle(cornerRadius: 8, style: .continuous).strokeBorder(theme.colors.borderDefault))
                }
                MonarchConsequenceList(
                    [
                        MonarchConsequence(.{{consequences.0.kind|raw}}, {{consequences.0.label}}, count: {{consequences.0.count}}),
                        MonarchConsequence(.{{consequences.1.kind|raw}}, {{consequences.1.label}}),
                    ]
                )
                MonarchTypeToConfirmInput(phrase: "\(count)", text: $typed, label: "Type \(count) to confirm")
                HStack(spacing: theme.spacing.space2) {
                    MonarchButton("Cancel", variant: .secondary, fullWidth: true) { isOpen = false }
                    MonarchButton({{trigger}}, variant: .danger, fullWidth: true) { deleteContacts() }
                        .disabled(!MonarchTypeToConfirmInput.matches(typed, phrase: "\(count)"))
                }
            }
        }
        .frame(maxHeight: .infinity, alignment: .top)
        .padding(theme.spacing.space4)
        .interactiveDismissDisabled(isRunning)
    }

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var isOpen = false
@State private var typed = ""
@State private var done = 0
@State private var isRunning = false
@State private var isFinished = false
@State private var failed: [String] = []
private let count = {{count}}
private var noun: String { count == 1 ? {{noun.one}} : {{noun.other}} }
private let sample = [{{sample.0}}, {{sample.1}}, {{sample.2}}]

private func deleteContacts() {
    isRunning = true
    Task {
        for _ in 1...count {
            // Delete on the server here; collect the ones that fail.
            try? await Task.sleep(for: .milliseconds(20))
            done += 1
        }
        isRunning = false
        isFinished = true
    }
}

examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var isOpen = false
@State private var typed = ""
@State private var done = 0
@State private var isRunning = false
@State private var isFinished = false
@State private var failed: [String] = []
private let count = 37
private var noun: String { count == 1 ? "contact" : "contacts" }
private let sample = ["Ada Park", "Ben Ortiz", "Cleo Ngata"]

private func deleteContacts() {
    isRunning = true
    Task {
        for _ in 1...count {
            // Delete on the server here; collect the ones that fail.
            try? await Task.sleep(for: .milliseconds(20))
            done += 1
        }
        isRunning = false
        isFinished = true
    }
}

